declare(strict_types=1);

/**
 * Adds to tests/fixtures/nextcloud-api/<major>.php the public surface of every Nextcloud Mail class the app names in
 * lib/ (plus the Mail objects of NextcloudApiUsage::EXTRA_CLASSES), parsed from the official Mail release pinned for
 * that major in mail-sources.json: the oldest Mail release for that Nextcloud that is not older than
 * AppEnablement::MINIMUM_VERSIONS. The Entity and QBMapper of the server release come along, so the magic getters
 * and the inherited methods of the Mail entities and mappers are in the surface. The sources are only tokenized,
 * never executed.
 *
 * Usage: php -d memory_limit=1G tests/fixtures/nextcloud-api/generate-mail.php <31..35> <archive directory>
 *
 * <archive directory> holds mail-<version>.tar.gz and server-<version>-<Entity|QBMapper>.php of that major, downloaded
 * from the URL of mail-sources.json and from raw.githubusercontent.com/nextcloud/server/v<version>/<path>; every file
 * is checked against its SHA256 first.
 */

use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\FixtureFile;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\LibScanner;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\NextcloudApiUsage;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\SourceParser;

require __DIR__ . '/../../../vendor/autoload.php';

[, $major, $archives] = $argv + [null, null, null];
$pins = json_decode((string)file_get_contents(__DIR__ . '/mail-sources.json'), true, 512, JSON_THROW_ON_ERROR);
if (!isset($pins[$major]) || !is_dir((string)$archives)) {
	fwrite(STDERR, "usage: php generate-mail.php <major of mail-sources.json> <verified archive directory>\n");
	exit(2);
}
$pin = $pins[$major];

/**
 * Refuses a file whose SHA256 is not the pinned one.
 *
 * @param string $file downloaded file
 * @param string $sha256 pinned checksum
 * @return void
 */
$verify = static function (string $file, string $sha256): void {
	if (!is_file($file) || hash_file('sha256', $file) !== $sha256) {
		throw new RuntimeException('Source SHA256 mismatch: ' . $file);
	}
};

$tree = sys_get_temp_dir() . '/mcp-mail-api-' . bin2hex(random_bytes(6));
mkdir($tree, recursive: true);
try {
	foreach ($pin['server']['files'] as $path => $sha256) {
		$file = $archives . '/server-' . $pin['server']['version'] . '-' . basename($path);
		$verify($file, $sha256);
		@mkdir($tree . '/' . dirname($path), recursive: true);
		copy($file, $tree . '/' . $path);
	}
	$archive = $archives . '/mail-' . $pin['mail']['version'] . '.tar.gz';
	$verify($archive, $pin['mail']['sha256']);
	$unpack = $tree . '/unpack';
	mkdir($unpack);
	(new PharData($archive))->extractTo($unpack);
	$roots = glob($unpack . '/*', GLOB_ONLYDIR) ?: [];
	if (count($roots) !== 1) {
		throw new RuntimeException('Expected one official app root');
	}
	mkdir($tree . '/apps');
	rename($roots[0], $tree . '/apps/mail');
	$version = (string)simplexml_load_file($tree . '/apps/mail/appinfo/info.xml')->version;
	if ($version !== $pin['mail']['version']) {
		throw new RuntimeException('Source app version mismatch: ' . $version);
	}

	$isMail = static fn (string $class): bool => str_starts_with($class, 'OCA\\Mail\\');
	$classes = array_values(array_unique(array_filter([
		...array_keys((new LibScanner(dirname(__DIR__, 3) . '/lib'))->classes()),
		...NextcloudApiUsage::EXTRA_CLASSES,
	], $isMail)));
	$fixture = require __DIR__ . '/' . $major . '.php';
	$fixture['classes'] = array_filter($fixture['classes'], static fn (string $class): bool => !$isMail($class), ARRAY_FILTER_USE_KEY);
	$parser = new SourceParser($tree);
	foreach ($classes as $class) {
		$surface = $parser->surface($class);
		if ($surface === null) {
			throw new RuntimeException('Official source lacks ' . $class);
		}
		$fixture['classes'][$class] = $surface;
	}
	ksort($fixture['classes']);
	$fixture['mailSources'] = $pin;

	$original = (string)file_get_contents(__DIR__ . '/' . $major . '.php');
	$header = substr($original, 0, (int)strpos($original, 'return ['));
	$header = (string)preg_replace('~// Mail surfaces generated[^\n]*\n~', '', $header);
	$header .= "// Mail surfaces generated by generate-mail.php; official versions/SHAs in mailSources.\n";
	FixtureFile::write(__DIR__ . '/' . $major . '.php', $header, $fixture);
	echo 'Generated Mail ' . $version . ' surfaces for NC' . $major . ': ' . implode(', ', $classes) . "\n";
} finally {
	$files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($tree, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
	foreach ($files as $file) {
		$file->isDir() ? rmdir($file->getPathname()) : unlink($file->getPathname());
	}
	rmdir($tree);
}
